#!/bin/bash
set -e
mkdir -p app/src/main/assets/www app/src/main/java/com/medicore/hms app/src/main/res/values app/src/main/res/mipmap-{mdpi,hdpi,xhdpi,xxhdpi,xxxhdpi} app/src/main/res/xml gradle/wrapper

echo "=== HTML ==="
echo "" | base64 -d > app/src/main/assets/www/index.html
echo "HTML: $(wc -c < app/src/main/assets/www/index.html) bytes"

echo "=== Gradle ==="
echo "rootProject.name = 'Rijong MediCore'
include ':app'" > settings.gradle
cat > build.gradle << 'EOF'
buildscript{repositories{google();mavenCentral()};dependencies{classpath 'com.android.tools.build:gradle:8.2.2'}}
allprojects{repositories{google();mavenCentral()}}
EOF
echo "org.gradle.jvmargs=-Xmx2048m
android.useAndroidX=true
android.enableJetifier=true" > gradle.properties
cat > app/build.gradle << 'EOF'
plugins{id 'com.android.application'}
android{
  namespace 'com.medicore.hms'
  compileSdk 34
  defaultConfig{applicationId "com.rijong.medicore";minSdk 24;targetSdk 34;versionCode 5;versionName "5.0.0"}
  buildTypes{debug{debuggable true};release{minifyEnabled false;signingConfig signingConfigs.debug}}
  compileOptions{sourceCompatibility JavaVersion.VERSION_17;targetCompatibility JavaVersion.VERSION_17}
}
dependencies{implementation 'androidx.appcompat:appcompat:1.6.1'}
EOF

echo "=== Manifest ==="
cat > app/src/main/AndroidManifest.xml << 'EOF'
<?xml version="1.0" encoding="utf-8"?>
<manifest xmlns:android="http://schemas.android.com/apk/res/android">
  <uses-permission android:name="android.permission.INTERNET"/>
  <application android:allowBackup="true" android:icon="@mipmap/ic_launcher" android:label="Rijong MediCore" android:theme="@style/AppTheme" android:usesCleartextTraffic="true">
    <activity android:name=".MainActivity" android:exported="true" android:screenOrientation="portrait" android:windowSoftInputMode="adjustResize">
      <intent-filter><action android:name="android.intent.action.MAIN"/><category android:name="android.intent.category.LAUNCHER"/></intent-filter>
    </activity>
    <provider android:name="androidx.core.content.FileProvider" android:authorities="com.rijong.medicore.fileprovider" android:exported="false" android:grantUriPermissions="true">
      <meta-data android:name="android.support.FILE_PROVIDER_PATHS" android:resource="@xml/file_paths"/>
    </provider>
  </application>
</manifest>
EOF
echo '<?xml version="1.0" encoding="utf-8"?><paths><cache-path name="receipts" path="receipts/"/><files-path name="files" path="."/></paths>' > app/src/main/res/xml/file_paths.xml

echo "=== MainActivity ==="
cat > app/src/main/java/com/medicore/hms/MainActivity.java << 'EOF'
package com.medicore.hms;
import android.annotation.SuppressLint;
import android.app.Activity;import android.app.AlertDialog;
import android.graphics.Color;import android.os.Build;import android.os.Bundle;
import android.print.*;import android.view.Window;import android.view.WindowManager;
import android.webkit.*;
public class MainActivity extends Activity {
  private WebView wv;
  @SuppressLint("SetJavaScriptEnabled")
  @Override protected void onCreate(Bundle s) {
    super.onCreate(s);
    requestWindowFeature(Window.FEATURE_NO_TITLE);
    getWindow().setFlags(WindowManager.LayoutParams.FLAG_FULLSCREEN,WindowManager.LayoutParams.FLAG_FULLSCREEN);
    if(Build.VERSION.SDK_INT>=21){getWindow().setStatusBarColor(Color.parseColor("#060e17"));getWindow().setNavigationBarColor(Color.parseColor("#060e17"));}
    wv=new WebView(this);wv.setBackgroundColor(Color.parseColor("#060e17"));setContentView(wv);
    WebSettings ws=wv.getSettings();
    ws.setJavaScriptEnabled(true);ws.setDomStorageEnabled(true);ws.setAllowFileAccess(true);
    ws.setAllowFileAccessFromFileURLs(true);ws.setAllowUniversalAccessFromFileURLs(true);
    ws.setBuiltInZoomControls(false);ws.setSupportZoom(false);
    ws.setUseWideViewPort(true);ws.setLoadWithOverviewMode(true);
    ws.setMixedContentMode(WebSettings.MIXED_CONTENT_ALWAYS_ALLOW);
    wv.addJavascriptInterface(new Object(){
      @JavascriptInterface public void printHtml(final String html){
        runOnUiThread(new Runnable(){public void run(){
          WebView pw=new WebView(MainActivity.this);
          pw.getSettings().setJavaScriptEnabled(true);
          pw.loadDataWithBaseURL(null,html,"text/html","UTF-8",null);
          pw.setWebViewClient(new WebViewClient(){
            @Override public void onPageFinished(WebView v,String u){
              PrintManager pm=(PrintManager)getSystemService(PRINT_SERVICE);
              PrintDocumentAdapter a=v.createPrintDocumentAdapter("Receipt");
              PrintAttributes pa=new PrintAttributes.Builder().setMediaSize(PrintAttributes.MediaSize.ISO_A4).setResolution(new PrintAttributes.Resolution("r","r",600,600)).setMinMargins(PrintAttributes.Margins.NO_MARGINS).build();
              pm.print("Rijong MediCore Receipt",a,pa);
            }
          });
        }});
      }
    },"AndroidBridge");
    wv.setWebViewClient(new WebViewClient());
    wv.setWebChromeClient(new WebChromeClient());
    wv.loadUrl("file:///android_asset/www/index.html");
  }
  @Override public void onBackPressed(){if(wv.canGoBack())wv.goBack();else new AlertDialog.Builder(this).setTitle("Exit").setMessage("Exit Rijong MediCore?").setPositiveButton("Exit",(d,w)->finish()).setNegativeButton("Cancel",null).show();}
  @Override protected void onResume(){super.onResume();if(wv!=null)wv.onResume();}
  @Override protected void onPause(){super.onPause();if(wv!=null)wv.onPause();}
  @Override protected void onDestroy(){if(wv!=null)wv.destroy();super.onDestroy();}
}
EOF

echo "=== Resources ==="
echo '<?xml version="1.0" encoding="utf-8"?><resources><string name="app_name">Rijong MediCore</string></resources>' > app/src/main/res/values/strings.xml
cat > app/src/main/res/values/styles.xml << 'EOF'
<?xml version="1.0" encoding="utf-8"?>
<resources><style name="AppTheme" parent="Theme.AppCompat.NoActionBar"><item name="android:windowBackground">#060e17</item><item name="android:statusBarColor">#060e17</item><item name="android:navigationBarColor">#060e17</item></style></resources>
EOF

echo "=== Icons ==="
echo "" | base64 -d > app/src/main/res/mipmap-mdpi/ic_launcher.png
cp app/src/main/res/mipmap-mdpi/ic_launcher.png app/src/main/res/mipmap-mdpi/ic_launcher_round.png
echo "" | base64 -d > app/src/main/res/mipmap-hdpi/ic_launcher.png
cp app/src/main/res/mipmap-hdpi/ic_launcher.png app/src/main/res/mipmap-hdpi/ic_launcher_round.png
echo "" | base64 -d > app/src/main/res/mipmap-xhdpi/ic_launcher.png
cp app/src/main/res/mipmap-xhdpi/ic_launcher.png app/src/main/res/mipmap-xhdpi/ic_launcher_round.png
echo "" | base64 -d > app/src/main/res/mipmap-xxhdpi/ic_launcher.png
cp app/src/main/res/mipmap-xxhdpi/ic_launcher.png app/src/main/res/mipmap-xxhdpi/ic_launcher_round.png
echo "" | base64 -d > app/src/main/res/mipmap-xxxhdpi/ic_launcher.png
cp app/src/main/res/mipmap-xxxhdpi/ic_launcher.png app/src/main/res/mipmap-xxxhdpi/ic_launcher_round.png
echo "Icons OK"

echo "=== Gradle wrapper ==="
echo "distributionBase=GRADLE_USER_HOME
distributionPath=wrapper/dists
distributionUrl=https\://services.gradle.org/distributions/gradle-8.4-bin.zip
zipStoreBase=GRADLE_USER_HOME
zipStorePath=wrapper/dists" > gradle/wrapper/gradle-wrapper.properties
wget -q https://services.gradle.org/distributions/gradle-8.4-bin.zip -O /tmp/gradle.zip
unzip -q -n /tmp/gradle.zip -d /tmp/
export PATH=$PATH:/tmp/gradle-8.4/bin
gradle wrapper --gradle-version 8.4
chmod +x gradlew

echo "=== Building APK ==="
./gradlew assembleDebug --no-daemon
echo "=== DONE ==="
ls -lh app/build/outputs/apk/debug/
